// spec: .qa/e2e/specs/moderation-menu.md 1.5 · тикеты #714b7a (AC 1, 10), #4d3a4c (AC 1, 10, 11)
// Две роли в одном сценарии (пишется вручную, не генератором): user4 (приложение, iPhone) жалуется на демо-пост «רוני»
// с текстом «QA-AUTO …» → admin (админка, десктоп) видит жалобу и закрывает её «דחיית דיווח» (это и есть очистка).
// @data: создаёт жалобу; в finally — закрытие жалобы в админке, если тест оборвался раньше.
import { test, expect } from '@playwright/test';
import { openFeed } from '../post-create/post-helpers';
import { ADMIN_URL, DEMO_POST, tapIn, adminAs, appApi, closeAdmin, closeApp, iphoneAs, myReportByDetails, qaText } from './mod-helpers';
import type { Api } from '../_shared/api';
import type { Page } from '@playwright/test';

// 8 причин (AC 10, решение раунда 2)
const REASONS = ['הטרדה', 'התחזות', 'תוכן מיני', 'אלימות או איום', 'ספאם', 'שנאה או אפליה', 'תוכן בלתי חוקי', 'סיבה אחרת'];

async function dismissInAdmin(admin: Page, reportId: string) {
  await admin.goto(`${ADMIN_URL}/reports?status=open&id=${reportId}`);
  const panel = admin.getByRole('region', { name: 'הדיווח הנבחר' });
  await panel.getByRole('button', { name: 'דחיית דיווח' }).click();
  const dlg = admin.getByRole('dialog').filter({ hasText: 'לדחות את הדיווח?' });
  await dlg.getByRole('textbox', { name: 'הערה פנימית' }).fill('QA-AUTO cleanup');
  const done = admin.waitForResponse((r) => r.request().method() === 'POST' && r.url().includes('/reports'));
  await dlg.getByRole('button', { name: 'דחיית דיווח' }).click();
  expect((await done).ok(), 'server action «דחיית דיווח»').toBeTruthy();
}

test.describe('בטיחות ומודרציה בצד המשתמש — жалоба', () => {
  test('Жалоба на чужой пост: 8 причин, «שליחת דיווח» → «תודה, הדיווח נשלח»; жалоба с текстом в админке /reports, закрытие «דחיית דיווח» @iphone @data (#714b7a #4d3a4c)', async ({ browser }) => {
    test.setTimeout(150_000);
    const user = await iphoneAs(browser, 'user4');
    let admin: Page | undefined;
    let api: Api | undefined;
    const details = qaText('4d3a4c', 'report');
    let reportId = '';
    let closed = false;
    try {
      api = await appApi(user);
      await openFeed(user);
      const post = user.getByText(DEMO_POST.text);
      const card = user.locator('div').filter({ has: post }).filter({ has: user.getByRole('button', { name: 'פעולות על הפוסט' }) }).last();
      await tapIn(user, card.getByRole('button', { name: 'פעולות על הפוסט' }));
      await tapIn(user, user.getByRole('button', { name: /דיווח על הפוסט/ }));

      // Экран жалобы (AC 10): адрес /report с типом и id цели, 8 причин, отправка недоступна без причины
      await user.waitForURL(/\/report\?targetType=post&targetId=/);
      expect(user.url()).toContain(`targetId=${DEMO_POST.id}`);
      await expect(user.getByText('למה את/ה מדווח/ת על הפוסט הזה?', { exact: false })).toBeVisible();
      await expect(user.getByRole('radio')).toHaveCount(REASONS.length);
      for (const r of REASONS) await expect(user.getByRole('radio', { name: r, exact: true })).toBeVisible();
      const send = user.getByRole('button', { name: 'שליחת דיווח' });
      await expect(send).toBeDisabled();

      await tapIn(user, user.getByRole('radio', { name: 'סיבה אחרת', exact: true }));
      await user.getByRole('textbox', { name: /ספר\/י לנו מה קרה/ }).fill(details);
      await expect(send).toBeEnabled();
      const posted = user.waitForResponse((r) => r.request().method() === 'POST' && /\/rest\/v1\/reports(\?|$)/.test(r.url()));
      await tapIn(user, send);
      const res = await posted;
      expect(res.status(), 'POST reports').toBe(201);
      expect(res.request().postDataJSON()).toMatchObject({ target_type: 'post', target_id: DEMO_POST.id, reason: 'other', details });
      await expect(user.getByText('תודה, הדיווח נשלח', { exact: false })).toBeVisible();

      const row = await myReportByDetails(api, details);
      expect(row?.status, 'жалоба создана со статусом open').toBe('open');
      reportId = row!.id;

      // Админка: жалоба дошла (AC 11) — текст, причина, номер R-XXXXXX
      admin = await adminAs(browser);
      await admin.goto(`${ADMIN_URL}/reports?status=open&id=${reportId}`);
      const panel = admin.getByRole('region', { name: 'הדיווח הנבחר' });
      await expect(panel.getByText(`R-${reportId.replace(/-/g, '').slice(-6).toUpperCase()}`, { exact: false })).toBeVisible();
      const item = panel.getByRole('listitem').filter({ hasText: details });
      await expect(item).toBeVisible();
      await expect(item).toContainText('סיבה: סיבה אחרת');

      // Закрытие (очистка) — статус «dismissed» у жалобы
      await dismissInAdmin(admin, reportId);
      await expect.poll(async () => (await myReportByDetails(api!, details))?.status).toBe('dismissed');
      closed = true;
    } finally {
      if (reportId && !closed) {
        try {
          admin ??= await adminAs(browser);
          await dismissInAdmin(admin, reportId);
        } catch {
          // жалобу закрыть вручную: /reports, текст «QA-AUTO 4d3a4c report …»
        }
      }
      await closeAdmin(admin);
      await closeApp(user, 'user4');
    }
  });
});
